import React, { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import { Textarea } from '../ui/textarea';
import { Checkbox } from '../ui/checkbox';
import { Alert, AlertDescription } from '../ui/alert';
import { clientService } from '../../services/clientService';
import axios from 'axios';
import { Mail, AlertCircle } from 'lucide-react';
import Swal from 'sweetalert2';

const API = process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000';

export const CreateClientModal = ({ isOpen, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    company_name: '',
    contact_person: '',
    email: '',
    phone: '',
    address: '',
    industry: '',
    notes: '',
  });
  const [sendInvitation, setSendInvitation] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // 1. Crear el cliente
      const clientResponse = await clientService.create(formData);

      // 2. Si se marcó enviar invitación, crear la invitación
      if (sendInvitation) {
        const token = localStorage.getItem('token');
        
        try {
          await axios.post(
            `${API}/api/invitations`,
            {
              email: formData.email,
              role: 'client',
              client_id: clientResponse._id,
            },
            { headers: { Authorization: `Bearer ${token}` } }
          );

          Swal.fire({
            icon: 'success',
            title: '¡Cliente Creado!',
            html: `
              <p><strong>${formData.company_name}</strong> ha sido creado exitosamente.</p>
              <br>
              <p>📧 Se ha enviado una invitación a: <strong>${formData.email}</strong></p>
              <p class="text-sm text-gray-600 mt-2">El cliente recibirá un email con instrucciones para crear su cuenta.</p>
            `,
            confirmButtonColor: '#16a34a',
          });
        } catch (inviteError) {
          console.error('Error al enviar invitación:', inviteError);
          Swal.fire({
            icon: 'warning',
            title: 'Cliente Creado',
            text: 'El cliente fue creado, pero hubo un error al enviar la invitación. Puedes reenviarla desde la gestión de usuarios.',
            confirmButtonColor: '#f59e0b',
          });
        }
      } else {
        Swal.fire({
          icon: 'success',
          title: '¡Cliente Creado!',
          text: `${formData.company_name} ha sido creado exitosamente`,
          confirmButtonColor: '#16a34a',
        });
      }

      onSuccess();
      onClose();
      resetForm();
    } catch (error) {
      console.error('Error:', error);
      
      // Manejo específico de errores de duplicados
      if (error.response?.status === 400) {
        const errorData = error.response.data;
        const field = errorData.field;
        const fieldName = field === 'email' ? 'email' : 'nombre de empresa';
        
        Swal.fire({
          icon: 'error',
          title: 'Cliente Duplicado',
          html: `
            <p>Ya existe un cliente con este <strong>${fieldName}</strong>.</p>
            <br>
            <p class="text-sm text-gray-600">${errorData.detail}</p>
          `,
          confirmButtonColor: '#dc2626',
        });
      } else {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: error.response?.data?.detail || 'Error al crear cliente',
          confirmButtonColor: '#dc2626',
        });
      }
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      company_name: '',
      contact_person: '',
      email: '',
      phone: '',
      address: '',
      industry: '',
      notes: '',
    });
    setSendInvitation(false);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Crear Nuevo Cliente</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit}>
          <div className="space-y-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="company_name">Nombre de Empresa *</Label>
                <Input
                  id="company_name"
                  name="company_name"
                  value={formData.company_name}
                  onChange={handleChange}
                  required
                  placeholder="Textiles ABC S.A."
                />
              </div>

              <div>
                <Label htmlFor="contact_person">Persona de Contacto *</Label>
                <Input
                  id="contact_person"
                  name="contact_person"
                  value={formData.contact_person}
                  onChange={handleChange}
                  required
                  placeholder="Juan Pérez"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  placeholder="contacto@empresa.com"
                />
              </div>

              <div>
                <Label htmlFor="phone">Teléfono *</Label>
                <Input
                  id="phone"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  required
                  placeholder="+593 99 123 4567"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="address">Dirección *</Label>
              <Input
                id="address"
                name="address"
                value={formData.address}
                onChange={handleChange}
                required
                placeholder="Av. Principal 123, Ciudad"
              />
            </div>

            <div>
              <Label htmlFor="industry">Industria *</Label>
              <Input
                id="industry"
                name="industry"
                value={formData.industry}
                onChange={handleChange}
                required
                placeholder="Textil, Alimentos, Construcción, etc."
              />
            </div>

            <div>
              <Label htmlFor="notes">Notas</Label>
              <Textarea
                id="notes"
                name="notes"
                value={formData.notes}
                onChange={handleChange}
                placeholder="Información adicional..."
                rows={3}
              />
            </div>

            {/* Opción para enviar invitación */}
            <div className="border-t pt-4">
              <div className="flex items-start space-x-3">
                <Checkbox
                  id="send_invitation"
                  checked={sendInvitation}
                  onCheckedChange={setSendInvitation}
                />
                <div className="flex-1">
                  <Label htmlFor="send_invitation" className="cursor-pointer font-semibold">
                    <Mail className="inline w-4 h-4 mr-1" />
                    Enviar invitación para acceso al sistema
                  </Label>
                  <p className="text-xs text-gray-500 mt-1">
                    El cliente recibirá un email con un link para crear su cuenta de acceso al sistema
                  </p>
                </div>
              </div>

              {sendInvitation && (
                <Alert className="mt-3 bg-blue-50 border-blue-200">
                  <AlertCircle className="h-4 w-4 text-blue-600" />
                  <AlertDescription className="text-sm text-blue-800">
                    <strong>Se enviará invitación a:</strong> {formData.email || '(ingrese un email)'}
                    <br />
                    El cliente podrá:
                    <ul className="list-disc list-inside mt-1 text-xs">
                      <li>Ver proyectos de su empresa</li>
                      <li>Descargar documentos</li>
                      <li>Consultar información</li>
                    </ul>
                  </AlertDescription>
                </Alert>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button 
              type="submit" 
              disabled={loading} 
              className="bg-green-600 hover:bg-green-700"
            >
              {loading ? 'Creando...' : 'Crear Cliente'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};
